size_t ngroups = BITMAP_GROUPS(binfo->nbits);
if (fill) {
    std::memset(bitmap, 0xff, ngroups * sizeof(bitmap_t));
    size_t trailing = binfo->nbits & BITMAP_GROUP_NBITS_MASK;
    if (trailing != 0) {
        bitmap_t mask = ((bitmap_t)1 << trailing) - 1;
        bitmap[ngroups - 1] = mask;
    }
} else {
    std::memset(bitmap, 0, ngroups * sizeof(bitmap_t));
}

